package com.bank.pricefeed.service;

import com.bank.pricefeed.config.PriceFeedConfig;
import com.bank.pricefeed.model.Symbol;
import com.bank.pricefeed.repository.SymbolRepository;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import java.math.BigDecimal;
import java.time.Duration;
import java.util.List;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class PriceFeedServiceTest {

    @Mock SymbolRepository symbolRepo;

    PriceFeedService service;

    @BeforeEach
    void setUp() {
        PriceFeedConfig config = new PriceFeedConfig(
            "https://api.nse-test.com", Duration.ofSeconds(5),
            Duration.ofSeconds(60), 3);

        when(symbolRepo.findByActiveTrue()).thenReturn(List.of(
            new Symbol("RELIANCE", "Reliance", "NSE", "Energy"),
            new Symbol("TCS", "TCS", "NSE", "IT")));

        service = new PriceFeedService(symbolRepo, config);
        service.init(); // manually call @PostConstruct in unit test
    }

    @Test
    void shouldReturnZeroPriceForCachedSymbol() {
        assertThat(service.getPrice("RELIANCE")).isEqualByComparingTo(BigDecimal.ZERO);
    }

    @Test
    void shouldUpdateAndReturnPrice() {
        service.updatePrice("RELIANCE", new BigDecimal("2450.50"));
        assertThat(service.getPrice("RELIANCE")).isEqualByComparingTo("2450.50");
    }

    @Test
    void shouldBeConnectedAfterInit() {
        assertThat(service.isConnected()).isTrue();
        assertThat(service.getCachedSymbolCount()).isEqualTo(2);
    }

    @Test
    void shouldThrowWhenNotConnected() {
        service.shutdown(); // simulate @PreDestroy
        assertThatThrownBy(() -> service.getPrice("RELIANCE"))
            .isInstanceOf(IllegalStateException.class)
            .hasMessageContaining("not connected");
    }
}
